import { CopyButton } from '@drizztdourden08/tessera';

const AboutActions = ({ debugInfo }: { debugInfo: () => string }) => (
  <CopyButton text={debugInfo} label="Copy debug info" showLabel variant="secondary" />
);

import { CopyValue } from '@drizztdourden08/tessera';

const RoomAddress = ({ address }: { address: string }) => (
  <CopyValue value={address} label="room address" mono truncate="middle" />
);

import { ShortcutList } from '@drizztdourden08/tessera';

const DockShortcuts = () => (
  <ShortcutList
    label="Dock shortcuts"
    groups={[
      {
        label: 'Any time',
        items: [
          { gesture: { icon: 'move', label: 'Drag title' }, description: 'Move to a dock edge, a pane, a tab or over the main view' },
          { keys: 'alt', description: 'Peek: widgets fold away while held' },
        ],
      },
      {
        label: 'While dragging',
        items: [
          { keys: 'shift', description: 'Swap with the pane under the pointer' },
          { keys: 'esc', description: 'Cancel the drag' },
        ],
      },
    ]}
  />
);

import { Sparkline } from '@drizztdourden08/tessera';

const FrameRateTrend = ({ samples }: { samples: readonly number[] }) => (
  <Sparkline values={samples} length={40} min={0} max={165} band={{ from: 0, to: 60, tone: 'danger' }} tone="success" dot label="Frame rate" />
);

import { StackedBar } from '@drizztdourden08/tessera';

const gigabytes = (value: number) => `${value.toFixed(1)} GB`;

const MemoryBar = () => (
  <StackedBar
    segments={[{ id: 'game', label: 'Game', value: 4.2 }, { id: 'browser', label: 'Browser', value: 1.8 }]}
    total={16}
    legend
    label="Memory"
    format={gigabytes}
  />
);

import { defineStatuses, StatusOf } from '@drizztdourden08/tessera';

const ENGINE_STATES = defineStatuses({
  ready: { label: 'Ready', tone: 'success' },
  building: { label: 'Setting up', tone: 'warning', pulse: true },
  failed: { label: 'Broken', tone: 'danger' },
  unknown: { label: 'Checking', tone: 'neutral' },
});

const EngineState = ({ state }: { state?: 'ready' | 'building' | 'failed' }) => (
  <StatusOf map={ENGINE_STATES} value={state} fallback="unknown" dot />
);

import { ContentHeader, HeaderAnchorNav, Icon } from '@drizztdourden08/tessera';

const GeneralHeader = ({ section, onSection }: { section: string; onSection: (id: string) => void }) => (
  <ContentHeader
    icon={<Icon name="settings" />}
    title="General"
    strip={<HeaderAnchorNav items={[{ id: 'startup', label: 'Startup' }, { id: 'tray', label: 'Tray' }]} activeId={section} onSelect={onSection} ariaLabel="General sections" />}
  />
);

import { FactsPanel, H2, InfoScreen, Logo } from '@drizztdourden08/tessera';

const AboutScreen = ({ onClose }: { onClose: () => void }) => (
  <InfoScreen
    title="About"
    onClose={onClose}
    lead={<><Logo brand="rotp" variant="app-icon" size="xl" title="" /><H2>Relic of the Past</H2></>}
    footer="Names and marks belong to their owners."
  >
    <FactsPanel label="This build" groups={[[{ label: 'Version', value: '0.9.2', mono: true }]]} />
  </InfoScreen>
);

import type { ReactNode } from 'react';
import { ScreenLayer } from '@drizztdourden08/tessera';

const KioskScreen = ({ children }: { children: ReactNode }) => (
  <ScreenLayer label="Kiosk" className="kiosk-screen">
    {children}
  </ScreenLayer>
);

import { Icon, ScreenPage, ScreenWindow } from '@drizztdourden08/tessera';

const SessionsScreen = ({ onClose }: { onClose: () => void }) => (
  <ScreenWindow title="Sessions" onClose={onClose}>
    <ScreenPage icon={<Icon name="layers" />} title="Friday async">
      Sessions list
    </ScreenPage>
  </ScreenWindow>
);

import { Button, Icon, ScreenWindow, ScrollArea } from '@drizztdourden08/tessera';

const SessionsScreen = ({ onClose }: { onClose: () => void }) => (
  <ScreenWindow title="Sessions" subtitle="Profile: mira" onClose={onClose}>
    <ScrollArea>Sessions list</ScrollArea>
  </ScreenWindow>
);

const PlayersScreen = ({ onClose }: { onClose: () => void }) => (
  <ScreenWindow title="Players" header={{ icon: <Icon name="users" />, actions: <Button size="sm">Invite</Button> }} onClose={onClose}>
    <ScrollArea>Players list</ScrollArea>
  </ScreenWindow>
);

import { Icon, StageScreen, Status } from '@drizztdourden08/tessera';

const Calibration = ({ onClose }: { onClose: () => void }) => (
  <StageScreen
    title="Input calibration"
    icon={<Icon name="gamepad-2" />}
    heading="Xbox controller"
    onClose={onClose}
    toolbar={<Status tone="success" variant="pill">Controller connected</Status>}
    done={{ onClick: onClose }}
  >
    Calibration steps
  </StageScreen>
);

import { Sparkline, StatTile } from '@drizztdourden08/tessera';

const FrameRateTile = ({ samples }: { samples: readonly number[] }) => (
  <StatTile
    label="Frame rate"
    value={samples[samples.length - 1] ?? 0}
    unit="fps"
    delta="+4"
    trend="up"
    chart={<Sparkline values={samples} min={0} max={165} tone="success" dot />}
  />
);

import { Icon, Strong, UtilityScreen } from '@drizztdourden08/tessera';

interface UpdateCheckProps {
  notes: string;
  onClose: () => void;
  onInstall: () => void;
  onReport: () => void;
}

const UpdateCheck = ({ notes, onClose, onInstall, onReport }: UpdateCheckProps) => (
  <UtilityScreen
    onClose={onClose}
    status={{ tone: 'info', icon: <Icon name="download" />, title: 'Update available', message: <>Version <Strong>0.10.0</Strong> is available</> }}
    notes={{ title: 'What is new in 0.10.0', children: notes }}
    report={{ onClick: onReport, footnote: 'Any earlier version can be picked above if something stops working.' }}
    actions={[
      { label: 'Later', variant: 'tertiary', onClick: onClose },
      { label: 'Install', variant: 'primary', onClick: onInstall },
    ]}
  />
);

import { Icon, WorkspaceScreen } from '@drizztdourden08/tessera';
import type { WorkspaceContent } from '@drizztdourden08/tessera';

interface HubProps {
  volume: number;
  setVolume: (value: number) => void;
  onClose: () => void;
}

const SettingsHub = ({ volume, setVolume, onClose }: HubProps) => {
  const content: WorkspaceContent = {
    groups: [{
      id: 'app',
      label: 'App',
      pages: [{
        id: 'audio',
        title: 'Audio',
        icon: <Icon name="volume-2" />,
        sections: [{
          id: 'output',
          title: 'Output',
          rows: [{ id: 'volume', title: 'Master volume', description: 'The loudness of every sound.', hint: 'Drag or use the arrow keys.', input: { kind: 'slider', value: volume, onChange: setVolume, min: 0, max: 100 } }],
        }],
      }],
    }],
  };
  return <WorkspaceScreen title="Settings" onClose={onClose} content={content} />;
};
